rejects(fn()=>$pages->adoptFieldtypes($page['id'],$page['version'],['foreign_key'],true),\Kulturhus\Native\Cms\Conflict::class,'a posted path cannot select another executable definition');
check($before===\Kulturhus\Native\Shared\Db::run($db,'SELECT * FROM khcms_pages WHERE id=?',[$page['id']])->fetch()&&$revisionCount===(int)$db->query('SELECT COUNT(*) FROM khcms_revisions')->fetchColumn(),'all rejected provider reviews preserve every original row and revision byte');
$page=$pages->adoptFieldtypes($page['id'],$page['version'],[$actual['key']],true);
check($page['custom_fields'][$actual['key']]==='Own real value!?'&&$page['field_definitions'][$actual['key']]['fieldtype']===$next,'confirmed real review applies the new native-enclosed normalizer and records its exact new binding');
check($published===\Kulturhus\Native\Shared\Db::run($db,'SELECT payload_json FROM khcms_revisions WHERE page_id=? AND revision=?',[$page['id'],$page['published_revision']])->fetchColumn()&&$page['body_html']==='<p>Own exact public body</p>','confirmed code review keeps the already published original and all unrelated content byte exact');
check(\Kulturhus\Native\Shared\Db::run($db,'SELECT action FROM khcms_revisions WHERE page_id=? AND revision=?',[$page['id'],$page['version']])->fetchColumn()==='fieldtypes-review','real provider review creates a distinct auditable private revision');
$page=$pages->publish($page['id'],$page['version']);check($page['custom_fields'][$actual['key']]==='Own real value!?','explicit publication after code review never normalizes the already adopted original a second time');
