check($pages->count($query)===1,'actual selector literal invokes provider forSearch normalization before canonical SQL comparison');
$actual=$model->saveField(array_replace($actual,['fieldtype'=>$type]),$actual['version']);
check($pages->count($query)===0,'current provider binding change excludes incompatible captured original values before count');
rejects(fn()=>$model->saveField(array_replace($actual,['type'=>'integer']),$actual['version']),DomainException::class,'registered model cannot silently change an existing native storage basis');
$child=$model->saveField(['key'=>'own_nested_provider','label'=>'Own nested reviewed text','type'=>'text','fieldtype'=>$type,'inputfield'=>$control]);
$model->saveField(['key'=>'own_provider_rows','label'=>'Own reviewed records','type'=>'repeater','fields'=>[$child['key']]]);
$model->saveField(['key'=>'own_provider_many','label'=>'Own reviewed values','type'=>'text','multiple'=>true,'fieldtype'=>$type,'inputfield'=>$control]);
