$nested=$pages->save(['template'=>'own_provider_collections','title'=>'Own nested original','slug'=>'own-provider-nested','custom_fields'=>['own_provider_rows'=>[['values'=>[$child['key']=>'Own nested value'],'editors'=>[$admin->user()['id']]]],'own_provider_many'=>['One','Two']]]);
