$empty=$pages->adoptFieldtypes($empty['id'],$empty['version'],['own_provider_rows.'.$child['key']],true);check($empty['custom_fields']['own_provider_rows']===[]&&$empty['field_definitions']['own_provider_rows']['item_definitions'][$child['key']]['fieldtype']===$next,'confirmed empty collection review updates only its original definition and never creates a synthetic item');
$ref=$registry->binding('own-fieldtypes','missing-page');$model->saveField(['key'=>'own_provider_ref','label'=>'Own checked reference','type'=>'page-reference','fieldtype'=>$ref]);$model->saveTemplate(['key'=>'own_provider_refpage','label'=>'Own checked references','renderer'=>'standard','fields'=>['own_provider_ref']]);$rowsBefore=(int)$db->query('SELECT COUNT(*) FROM khcms_pages')->fetchColumn();
rejects(fn()=>$pages->save(['template'=>'own_provider_refpage','title'=>'Own invalid normalized reference','slug'=>'own-provider-invalid-reference','custom_fields'=>['own_provider_ref'=>$page['id']]]),InvalidArgumentException::class,'custom normalized references still require a real native original in the same club');
check($rowsBefore===(int)$db->query('SELECT COUNT(*) FROM khcms_pages')->fetchColumn(),'invalid callback result rolls back without leaving a partial page');
